      activeLesson = mod.lessons.find(l => l.id === activeIds.lessonId);
    }
  }

  const videoId = getYoutubeId(activeLesson?.videoUrl);

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-[#0a0f1a] flex flex-col" dir={lang === 'ar' ? 'rtl' : 'ltr'}>
