            <span className="px-2 py-1 bg-red-500/20 text-red-500 text-[10px] uppercase font-bold rounded flex items-center gap-1">
              <span className="w-1.5 h-1.5 rounded-full bg-red-500 animate-pulse"></span> LIVE
            </span>
