      <div className="flex-1 flex gap-6 min-h-0">
        {/* Toolbar */}
        <div className="w-16 glass-card rounded-2xl flex flex-col items-center py-4 gap-4">
          {[
            { id: 'cursor', icon: MousePointer2 },
            { id: 'text', icon: Type },
            { id: 'square', icon: Square },
            { id: 'circle', icon: Circle },
          ].map(tool => (
            <button
              key={tool.id}
              onClick={() => setActiveTool(tool.id)}
              className={`p-3 rounded-xl transition-colors ${activeTool === tool.id ? 'bg-cyan-500 text-white shadow-lg shadow-cyan-500/30' : 'text-slate-500 hover:bg-cyan-100 dark:hover:bg-slate-50 dark:bg-slate-800'}`}
            >
              <tool.icon size={20} />
            </button>
          ))}
        </div>

        {/* Board Canvas */}
        <div 
          ref={boardRef}
          onClick={handleBoardClick}
          className="flex-1 glass-card rounded-2xl bg-grid-slate-200 dark:bg-grid-white/[0.02] bg-[size:20px_20px] relative overflow-hidden cursor-crosshair"
        >
          {/* Render Elements */}
          {elements.map(el => (
            <motion.div
              key={el.id}
              initial={{ scale: 0, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
