      toast.error(lang === 'ar' ? 'حدث خطأ أثناء الحفظ' : 'Error saving article');
    } finally {
      setIsSavingArticle(false);
    }
  };

  const handleDeleteArticle = (id) => {
    confirmAction(
      lang === 'ar' ? 'تأكيد الحذف' : 'Confirm Deletion',
