                <SortableModule 
                  key={mod.id} 
                  module={mod} 
                  onRemove={removeModule}
                  onUpdateModule={updateModule}
                  onAddLesson={addLesson}
                  onRemoveLesson={removeLesson}
                  onUpdateLesson={updateLesson}
