    { id: 'team', icon: Users, label: lang === 'ar' ? 'نظرة عامة على الفريق' : 'Team Overview' },
    { id: 'reports', icon: TrendingUp, label: lang === 'ar' ? 'تقارير التقدم' : 'Progress Reports' },
    { id: 'approvals', icon: ShieldCheck, label: lang === 'ar' ? 'طلبات الموافقة' : 'Approvals' },
    { id: 'notifications', icon: Bell, label: lang === 'ar' ? 'الإشعارات' : 'Notifications' },
    { id: 'profile', icon: Settings, label: lang === 'ar' ? 'الملف الشخصي' : 'Profile & Settings' },
  ];

  const cardVariants = {
    hidden: { opacity: 0, y: 20 },
    visible: (i) => ({ opacity: 1, y: 0, transition: { delay: i * 0.08, duration: 0.4, ease: 'easeOut' } }),
  };

  return (
    <div className={`flex flex-col md:flex-row gap-6 animate-fade-in-up pb-24 md:pb-10 min-h-screen relative ${lang === 'ar' ? 'md:flex-row-reverse' : ''}`}>
      
      {/* Mobile Header */}
      <div className="md:hidden flex items-center justify-between bg-white/80 dark:bg-slate-900/80 backdrop-blur-md p-4 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-sm mb-2 sticky top-20 z-40">
        <div>
          <h2 className="text-xl font-sans font-bold tracking-tight font-bold text-[#1e3a5f] dark:text-white">{lang === 'ar' ? 'بوابة المشرف' : 'Supervisor Portal'}</h2>
          <p className="text-xs text-slate-500 dark:text-slate-400 mt-0.5">{supervisorName}</p>
        </div>
        <div className="w-10 h-10 rounded-full bg-gradient-to-tr from-indigo-600 to-purple-500 flex items-center justify-center text-white font-bold shadow-lg">
