                                  <UploadCloud size={18} />
                                  <span className="truncate max-w-[200px]">{lessonFile ? lessonFile.name : (lang === 'ar' ? 'رفع ملف (PDF/فيديو)' : 'Upload File (PDF/Video)')}</span>
