                          gradedItems[sub.id] !== undefined
                            ? 'border-emerald-200 dark:border-emerald-900/40 bg-emerald-50/50 dark:bg-emerald-900/10'
                            : 'border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900/50'
