                    { label: lang === 'ar' ? 'نسبة الحضور' : 'Attendance Rate', value: `${analyticsData.attendanceRate}%`, icon: Users, gradient: 'from-emerald-500 to-teal-500', bg: 'bg-emerald-50 dark:bg-emerald-900/20' },
