                    { label: lang === 'ar' ? 'المقررات النشطة' : 'Active Courses', value: analyticsData.coursesActive, icon: BookOpen, gradient: 'from-amber-500 to-orange-500', bg: 'bg-amber-50 dark:bg-amber-900/20' },
