                        <Play size={16}/> {session.status === 'upcoming' ? (lang === 'ar' ? 'انضمام للجلسة' : 'Join Session') : (lang === 'ar' ? 'انتهت الجلسة' : 'Session Ended')}
                      </button>
                    </motion.div>
                  ))}
                </div>
