                    <h4 className="font-bold text-[#1e3a5f] dark:text-white mb-4 flex items-center gap-2">
                      <Award size={18} className="text-amber-500"/> {lang === 'ar' ? 'أفضل الطلاب' : 'Top Students'}
                    </h4>
                    <div className="space-y-3">
