                          {val}%
                        </div>
                      </motion.div>
                    ))}
                  </div>
                  <div className="flex justify-between mt-2 text-[10px] text-slate-600 dark:text-slate-400 font-bold">
                    {['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'].map(m => (
                      <span key={m}>{m}</span>
                    ))}
                  </div>
                </motion.div>
              </div>
            )}

