            {activeTab === 'profile' && (
              <UserProfileSettings currentUser={{
                name: teacherName,
                role: 'teacher',
                email: teacherEmail,
                badges: currentUser?.badges || ['instructor', 'ai_expert'],
                membershipId: currentUser?.membershipId || 'GITM-TCH-001'
              }} />
            )}

