            id: article.url,
            title: article.title,
            originalTitle: article.title,
            by: article.source.name,
            url: article.url,
            image: article.image,
            isApi: true
          }));
          setNews(stories);
        } else {
          setNews(MOCK_NEWS);
        }
        setLoading(false);
      } catch (err) {
